require_once __DIR__.'/lib/staging-common.php';$root=Ch247Staging::root($argv[1]??'');$output=$argv[2]??null;require$root.'/init.php';use WHMCS\Database\Capsule;$environment=Ch247Staging::verifyEnvironment($root);
function ch247TableEvidence($table,$columns){if(!Capsule::schema()->hasTable($table))return array('exists'=>false,'count'=>0);$available=array_values(array_filter($columns,function($c)use($table){return Capsule::schema()->hasColumn($table,$c);}));$hash=hash_init('sha256');$count=0;Capsule::table($table)->select($available)->orderBy('id')->chunk(500,function($rows)use(&$count,$hash,$available){foreach($rows as$row){$safe=array();foreach($available as$c)$safe[$c]=$row->{$c};hash_update($hash,json_encode($safe,JSON_UNESCAPED_SLASHES)."\n");$count++;}});return array('exists'=>true,'count'=>$count,'columns'=>$available,'sha256'=>hash_final($hash));}
