$tables=array();foreach($definitions as$table=>$columns)$tables[$table]=ch247TableEvidence($table,$columns);$cloud=array();foreach(Capsule::select("show tables like 'mod_cloudhost247_%'")as$row){$name=array_values((array)$row)[0];$cloud[$name]=array('count'=>(int)Capsule::table($name)->count());}ksort($cloud);
$totals=array();foreach(array('tblinvoices'=>array('total','balance','credit'),'tblinvoiceitems'=>array('amount'),'tblaccounts'=>array('amountin','fees','amountout'),'tblclients'=>array('credit'),'tblhosting'=>array('amount'),'tbldomains'=>array('recurringamount'))as$table=>$columns)if(Capsule::schema()->hasTable($table))foreach($columns as$column)if(Capsule::schema()->hasColumn($table,$column))$totals[$table.'.'.$column]=(string)Capsule::table($table)->sum($column);
